'use client';

/**
 * @file FeedbackCards.tsx (Post-Interview Qualitative Analysis Cards)
 * @description Renders qualitative evaluation findings generated by the feedback microservice:
 * 1. Key Strengths (green cards with checkmarks and code-block parsing)
 * 2. Areas for Improvement (rose cards with minus badges)
 * 3. Targeted Code Improvements (indigo cards for algorithmic and architectural optimizations)
 * 4. Question-by-Question Scoring Breakdown (turn score badges and feedback)
 * 5. Actionable Recommendations (numbered progressive improvement steps)
 */

import React from 'react';
import { CheckCircle2, XCircle, BookOpen, Code2, CheckSquare } from 'lucide-react';

/**
 * Parses inline backticks (e.g. `O(n log n)`, `hash_map`) into stylized monospace code tags.
 */
function renderWithCodeBlocks(text: string) {
  const parts = text.split(/(`[^`]+`)/g);
  return parts.map((part, i) =>
    part.startsWith('`') && part.endsWith('`') ? (
      <code key={i} className="bg-slate-100 text-blue-700 px-1.5 py-0.5 rounded text-xs font-mono font-bold">
        {part.slice(1, -1)}
      </code>
    ) : (
      <span key={i}>{part}</span>
    )
  );
}

/**
 * Props passed to FeedbackCards.
 */
interface FeedbackCardsProps {
  /** Array of strengths highlighted by the evaluation model */
  strengths: string[];
  /** Array of weaknesses or missed edge cases */
  weaknesses: string[];
  /** Array of actionable next steps for the candidate */
  recommendations: string[];
  /** Suggested code optimizations */
  code_improvements?: string[];
  /** Turn-by-turn question breakdown */
  question_scores?: {
    turn: number;
    question_summary: string;
    score: number;
    feedback: string;
  }[];
}

/**
 * FeedbackCards Component.
 */
export default function FeedbackCards({
  strengths,
  weaknesses,
  recommendations,
  code_improvements = [],
  question_scores = [],
}: FeedbackCardsProps) {
  return (
    <>
      {/* ── Strengths & Weaknesses 2-Column Grid ── */}
      <section className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Strengths Card */}
        <div className="bg-emerald-50/60 border border-emerald-200 p-6 rounded-2xl flex flex-col gap-4 shadow-sm">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="w-5 h-5 text-emerald-600" />
            <h3 className="text-slate-800 font-bold">Key Strengths</h3>
            <span className="ml-auto text-[10px] font-bold text-emerald-600 bg-emerald-100 border border-emerald-200 px-2 py-0.5 rounded-full">
              {strengths.length} identified
            </span>
          </div>
          {strengths.length > 0 ? (
            <ul className="flex flex-col gap-3">
              {strengths.map((str, idx) => (
                <li key={idx} className="flex gap-2.5 text-sm leading-relaxed text-slate-700 bg-white/70 p-3 rounded-xl border border-emerald-100/60">
                  <span className="text-emerald-600 font-black select-none mt-0.5 text-base leading-none">&#10003;</span>
                  <span>{renderWithCodeBlocks(str)}</span>
                </li>
              ))}
            </ul>
          ) : (
            <div className="flex flex-col items-center gap-2 py-6 text-center">
              <CheckCircle2 className="w-10 h-10 text-slate-200" />
              <p className="text-xs text-slate-400 italic leading-relaxed max-w-[200px]">
                No strengths identified — complete a full interview session for detailed analysis.
              </p>
            </div>
          )}
        </div>

        {/* Weaknesses Card */}
        <div className="bg-rose-50/60 border border-rose-200 p-6 rounded-2xl flex flex-col gap-4 shadow-sm">
          <div className="flex items-center gap-2">
            <XCircle className="w-5 h-5 text-rose-600" />
            <h3 className="text-slate-800 font-bold">Areas for Improvement</h3>
            <span className="ml-auto text-[10px] font-bold text-rose-600 bg-rose-100 border border-rose-200 px-2 py-0.5 rounded-full">
              {weaknesses.length} found
            </span>
          </div>
          {weaknesses.length > 0 ? (
            <ul className="flex flex-col gap-3">
              {weaknesses.map((weak, idx) => (
                <li key={idx} className="flex gap-2.5 text-sm leading-relaxed text-slate-700 bg-white/70 p-3 rounded-xl border border-rose-100/60">
                  <span className="text-rose-500 font-black select-none mt-0.5 text-base leading-none">&minus;</span>
                  <span>{renderWithCodeBlocks(weak)}</span>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-xs text-slate-500 italic leading-relaxed py-2">No areas for improvement identified.</p>
          )}
        </div>
      </section>

      {/* ── Targeted Code Improvements Section (if present) ── */}
      {code_improvements && code_improvements.length > 0 && (
        <section className="bg-indigo-50/50 border border-indigo-200 p-6 rounded-2xl flex flex-col gap-4 shadow-sm">
          <div className="flex items-center gap-2">
            <Code2 className="w-5 h-5 text-indigo-600" />
            <h3 className="text-slate-800 font-bold">Suggested Code Optimizations</h3>
            <span className="ml-auto text-[10px] font-bold text-indigo-700 bg-indigo-100 border border-indigo-200 px-2 py-0.5 rounded-full">
              {code_improvements.length} suggestions
            </span>
          </div>
          <ul className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {code_improvements.map((ci, idx) => (
              <li
                key={idx}
                className="flex gap-2.5 text-sm leading-relaxed text-slate-700 bg-white/80 p-3.5 rounded-xl border border-indigo-100 shadow-2xs"
              >
                <span className="text-indigo-600 font-black select-none mt-0.5 text-base leading-none">&rarr;</span>
                <span>{renderWithCodeBlocks(ci)}</span>
              </li>
            ))}
          </ul>
        </section>
      )}

      {/* ── Question-by-Question Scoring Breakdown (if present) ── */}
      {question_scores && question_scores.length > 0 && (
        <section className="bg-white border border-blue-100 p-6 rounded-2xl flex flex-col gap-4 shadow-sm">
          <div className="flex items-center gap-2">
            <CheckSquare className="w-5 h-5 text-blue-600" />
            <h3 className="text-slate-800 font-bold">Question Performance Breakdown</h3>
            <span className="ml-auto text-[10px] font-bold text-blue-600 bg-blue-50 border border-blue-200 px-2 py-0.5 rounded-full">
              {question_scores.length} questions evaluated
            </span>
          </div>
          <div className="space-y-3">
            {question_scores.map((qs, idx) => (
              <div
                key={idx}
                className="bg-slate-50 border border-slate-200 rounded-xl p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3 hover:border-blue-200 transition-colors"
              >
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-blue-100 text-blue-700 uppercase tracking-wider">
                      Turn {qs.turn || idx + 1}
                    </span>
                    <span className="text-xs font-bold text-slate-800 truncate">
                      {qs.question_summary}
                    </span>
                  </div>
                  <p className="text-xs text-slate-600 leading-relaxed font-medium">
                    {qs.feedback}
                  </p>
                </div>
                <div className="shrink-0 flex items-center gap-1.5 self-start sm:self-center">
                  <span
                    className={`text-sm font-extrabold px-2.5 py-1 rounded-lg border ${
                      qs.score >= 8
                        ? 'bg-emerald-50 text-emerald-700 border-emerald-200'
                        : qs.score >= 5
                        ? 'bg-amber-50 text-amber-700 border-amber-200'
                        : 'bg-rose-50 text-rose-700 border-rose-200'
                    }`}
                  >
                    {qs.score}/10
                  </span>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* ── Actionable Recommendations Section ── */}
      <section className="bg-white border border-blue-100 p-6 rounded-2xl flex flex-col gap-4 shadow-sm">
        <div className="flex items-center gap-2">
          <BookOpen className="w-5 h-5 text-blue-600" />
          <h3 className="text-slate-800 font-bold">Actionable Recommendations</h3>
          <span className="ml-auto text-[10px] font-bold text-blue-600 bg-blue-50 border border-blue-200 px-2 py-0.5 rounded-full">
            {recommendations.length} steps
          </span>
        </div>
        {recommendations.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {recommendations.map((rec, idx) => (
              <div
                key={idx}
                className="bg-gradient-to-br from-blue-50/60 to-slate-50/40 border border-blue-100 p-4 rounded-xl hover:border-blue-300 hover:shadow-md transition-all flex items-start gap-3 group"
              >
                <span className="w-7 h-7 rounded-full bg-blue-600 text-white text-xs font-black flex items-center justify-center flex-shrink-0 mt-0.5 shadow-sm group-hover:scale-110 transition-transform">
                  {idx + 1}
                </span>
                <p className="text-sm leading-relaxed text-slate-700 font-medium">{renderWithCodeBlocks(rec)}</p>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-xs text-slate-500 italic">No recommendations available.</p>
        )}
      </section>
    </>
  );
}
